package com.example.starter.fermentation;

import com.example.starter.fermentation.api.BatchDtos.CreateBatchRequest;
import com.example.starter.fermentation.api.YeastDtos.PitchYeastRequest;
import com.example.starter.fermentation.error.ApiException;
import com.example.starter.fermentation.service.IdempotencyService.StoredResponse;
import com.example.starter.fermentation.service.YeastService;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.annotation.Import;
import org.springframework.jdbc.core.JdbcTemplate;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * 同一酵母单元被两个发酵批次并发选中时的投酵互斥测试（真实并发 + H2 条件更新/行锁验证）。
 */
@SpringBootTest
@Import(TestClockConfig.class)
class YeastConcurrencyTest {

    @Autowired
    private YeastService yeastService;

    @Autowired
    private JdbcTemplate jdbc;

    @Test
    @DisplayName("两批并发投同一酵母：恰好一方成功(200)，另一方409，占用只属于胜方且败方批次仍满罐")
    void concurrentPitchSameYeastOnlyOneSucceeds() throws Exception {
        clean();
        jdbc.update("INSERT INTO yeast_unit (unit_code, generation, status, version, created_at)"
                + " VALUES ('Y-CONC-1', 0, 'AVAILABLE', 1, ?)", java.sql.Timestamp.valueOf(BaseFermentationTest.T0));
        long batchA = createBatchDirect("B-CONC-A", "TANK-1");
        long batchB = createBatchDirect("B-CONC-B", "TANK-2");

        int threads = 2;
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch ready = new CountDownLatch(threads);
        CountDownLatch go = new CountDownLatch(1);
        AtomicInteger success = new AtomicInteger();
        AtomicInteger conflicted = new AtomicInteger();
        AtomicInteger unexpected = new AtomicInteger();
        List<Long> winners = java.util.Collections.synchronizedList(new ArrayList<>());

        List<Future<?>> futures = new ArrayList<>();
        futures.add(pool.submit(pitchTask(batchA, "req-pitch-A", ready, go,
                success, conflicted, unexpected, winners)));
        futures.add(pool.submit(pitchTask(batchB, "req-pitch-B", ready, go,
                success, conflicted, unexpected, winners)));

        assertTrue(ready.await(10, TimeUnit.SECONDS), "线程就绪超时");
        go.countDown();
        for (Future<?> f : futures) {
            f.get(30, TimeUnit.SECONDS);
        }
        pool.shutdown();
        assertTrue(pool.awaitTermination(10, TimeUnit.SECONDS), "线程池终止超时");

        assertEquals(1, success.get(), "并发投酵应仅一方成功");
        assertEquals(1, conflicted.get(), "另一方应返回 409");
        assertEquals(0, unexpected.get(), "不应出现其他结果");
        assertEquals(1, winners.size());

        // 单元最终 IN_USE，占用批次唯一且为胜方，版本只增一次
        Integer statusCount = jdbc.queryForObject(
                "SELECT COUNT(*) FROM yeast_unit WHERE unit_code = 'Y-CONC-1' AND status = 'IN_USE'",
                Integer.class);
        assertEquals(1, statusCount);
        Long occupant = jdbc.queryForObject(
                "SELECT occupied_by_batch_id FROM yeast_unit WHERE unit_code = 'Y-CONC-1'",
                Long.class);
        assertEquals(winners.get(0), occupant, "占用方必须是投酵胜方");
        Integer version = jdbc.queryForObject(
                "SELECT version FROM yeast_unit WHERE unit_code = 'Y-CONC-1'", Integer.class);
        assertEquals(2, version, "仅成功一方使版本 +1");

        // 恰好一个批次进入主酵，败方仍为满罐
        Integer mainCount = jdbc.queryForObject(
                "SELECT COUNT(*) FROM fermentation_batch WHERE status = 'MAIN_FERMENT'", Integer.class);
        assertEquals(1, mainCount);
        Integer filledCount = jdbc.queryForObject(
                "SELECT COUNT(*) FROM fermentation_batch WHERE status = 'FILLED'", Integer.class);
        assertEquals(1, filledCount);
    }

    private Callable<Void> pitchTask(long batchId, String requestId, CountDownLatch ready,
                                     CountDownLatch go, AtomicInteger success,
                                     AtomicInteger conflicted, AtomicInteger unexpected,
                                     List<Long> winners) {
        return () -> {
            ready.countDown();
            assertTrue(go.await(10, TimeUnit.SECONDS), "并发闸门等待超时");
            try {
                StoredResponse response = yeastService.pitch(batchId, new PitchYeastRequest(
                        requestId, "Y-CONC-1", 1, BaseFermentationTest.T0));
                if (response.status() == 200) {
                    success.incrementAndGet();
                    winners.add(batchId);
                } else {
                    unexpected.incrementAndGet();
                }
            } catch (ApiException e) {
                if (e.status().value() == 409) {
                    conflicted.incrementAndGet();
                } else {
                    unexpected.incrementAndGet();
                }
            }
            return null;
        };
    }

    private long createBatchDirect(String batchNo, String tankCode) {
        Long tankId = jdbc.queryForObject(
                "SELECT id FROM fermentation_tank WHERE tank_code = ?", Long.class, tankCode);
        jdbc.update("INSERT INTO fermentation_batch (batch_no, tank_id, curve_code, curve_version,"
                        + " status, filled_at, maturation_extended, active_tank_key)"
                        + " VALUES (?, ?, 'LAGER-CURVE', 1, 'FILLED', ?, 0, ?)",
                batchNo, tankId, java.sql.Timestamp.valueOf(BaseFermentationTest.T0), tankCode);
        return jdbc.queryForObject(
                "SELECT id FROM fermentation_batch WHERE batch_no = ?", Long.class, batchNo);
    }

    private void clean() {
        jdbc.update("DELETE FROM yeast_recovery_record");
        jdbc.update("DELETE FROM idempotency_record");
        jdbc.update("DELETE FROM fermentation_batch");
        jdbc.update("DELETE FROM yeast_unit");
    }
}

package com.example.starter.fermentation.repository;

import com.example.starter.fermentation.domain.YeastRecoveryRecord;
import com.example.starter.fermentation.domain.YeastStatus;
import com.example.starter.fermentation.domain.YeastUnit;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

import java.math.BigDecimal;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;
import java.util.Optional;

/**
 * 合成酵母单元与回收记录数据访问。所有 SQL 参数化；
 * 同酵母并发投酵由条件更新（status/version 匹配才占用）与唯一约束共同兜底，
 * 按事务提交顺序裁决最新代次与状态。
 */
@Repository
public class YeastRepository {

    private static final RowMapper<YeastUnit> UNIT_MAPPER = (rs, rowNum) -> new YeastUnit(
            rs.getLong("id"),
            rs.getString("unit_code"),
            rs.getInt("generation"),
            YeastStatus.valueOf(rs.getString("status")),
            toLdt(rs.getTimestamp("last_recovered_at")),
            (Long) rs.getObject("occupied_by_batch_id"),
            rs.getInt("version"),
            toLdt(rs.getTimestamp("created_at")));

    private static final RowMapper<YeastRecoveryRecord> RECOVERY_MAPPER = (rs, rowNum) ->
            new YeastRecoveryRecord(
                    rs.getLong("id"),
                    rs.getString("yeast_unit_code"),
                    rs.getLong("batch_id"),
                    rs.getBigDecimal("viability_percent"),
                    rs.getInt("contaminated") != 0,
                    rs.getInt("qualified") != 0,
                    rs.getInt("generation_after"),
                    toLdt(rs.getTimestamp("recovered_at")),
                    toLdt(rs.getTimestamp("created_at")));

    private final JdbcTemplate jdbc;

    public YeastRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    private static LocalDateTime toLdt(Timestamp ts) {
        return ts == null ? null : ts.toLocalDateTime();
    }

    /**
     * 登记酵母单元：代次 0、AVAILABLE、版本 1、无占用、无回收时刻。
     *
     * @return 生成 ID
     */
    public long insert(String unitCode, LocalDateTime createdAt) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO yeast_unit (unit_code, generation, status, last_recovered_at,"
                            + " occupied_by_batch_id, version, created_at)"
                            + " VALUES (?, 0, 'AVAILABLE', NULL, NULL, 1, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, unitCode);
            ps.setTimestamp(2, Timestamp.valueOf(createdAt));
            return ps;
        }, keyHolder);
        return keyHolder.getKey().longValue();
    }

    /** 按编号查酵母单元，不存在返回空。 */
    public Optional<YeastUnit> findByCode(String unitCode) {
        return jdbc.query("SELECT * FROM yeast_unit WHERE unit_code = ?",
                rs -> rs.next() ? Optional.of(UNIT_MAPPER.mapRow(rs, 1)) : Optional.empty(),
                unitCode);
    }

    /**
     * 原子占用：仅当单元仍 AVAILABLE、版本匹配且当前代次不超过 5 时置 IN_USE 并绑定批次，版本 +1。
     *
     * <p>并发两批投同一酵母时，先取得行锁的事务提交后，另一事务条件不再匹配，更新 0 行。
     *
     * @return 实际更新行数；0 表示已被占用、版本变化或代次超限，调用方应重读裁决
     */
    public int tryOccupy(String unitCode, int expectedVersion, long batchId, int maxGeneration) {
        return jdbc.update("UPDATE yeast_unit SET status = 'IN_USE', occupied_by_batch_id = ?,"
                        + " version = version + 1"
                        + " WHERE unit_code = ? AND version = ? AND status = 'AVAILABLE'"
                        + " AND generation <= ?",
                batchId, unitCode, expectedVersion, maxGeneration);
    }

    /**
     * 回收同事务落库：更新状态/代次/最近回收时刻、解除批次占用，版本 +1。
     * 仅当版本匹配时更新；不合格时 newGeneration 传原代次（不加 1）。
     *
     * @return 实际更新行数；0 表示版本不匹配
     */
    public int applyRecovery(String unitCode, int expectedVersion, YeastStatus newStatus,
                             int newGeneration, LocalDateTime recoveredAt) {
        return jdbc.update("UPDATE yeast_unit SET status = ?, generation = ?,"
                        + " last_recovered_at = ?, occupied_by_batch_id = NULL, version = version + 1"
                        + " WHERE unit_code = ? AND version = ?",
                newStatus.name(), newGeneration, Timestamp.valueOf(recoveredAt),
                unitCode, expectedVersion);
    }

    /** 插入回收记录（uk_recovery_batch 保证每批次仅一条），返回生成 ID。 */
    public long insertRecovery(String unitCode, long batchId, BigDecimal viabilityPercent,
                               boolean contaminated, boolean qualified, int generationAfter,
                               LocalDateTime recoveredAt, LocalDateTime createdAt) {
        KeyHolder keyHolder = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO yeast_recovery_record (yeast_unit_code, batch_id, viability_percent,"
                            + " contaminated, qualified, generation_after, recovered_at, created_at)"
                            + " VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, unitCode);
            ps.setLong(2, batchId);
            ps.setBigDecimal(3, viabilityPercent);
            ps.setInt(4, contaminated ? 1 : 0);
            ps.setInt(5, qualified ? 1 : 0);
            ps.setInt(6, generationAfter);
            ps.setTimestamp(7, Timestamp.valueOf(recoveredAt));
            ps.setTimestamp(8, Timestamp.valueOf(createdAt));
            return ps;
        }, keyHolder);
        return keyHolder.getKey().longValue();
    }

    /** 按批次查回收记录，不存在返回空。 */
    public Optional<YeastRecoveryRecord> findRecoveryByBatch(long batchId) {
        return jdbc.query("SELECT * FROM yeast_recovery_record WHERE batch_id = ?",
                rs -> rs.next() ? Optional.of(RECOVERY_MAPPER.mapRow(rs, 1)) : Optional.empty(),
                batchId);
    }

    /** 按单元编号查回收记录链（按回收时刻升序，再按 ID 稳定排序）。 */
    public List<YeastRecoveryRecord> findRecoveriesByUnit(String unitCode) {
        return jdbc.query("SELECT * FROM yeast_recovery_record WHERE yeast_unit_code = ?"
                        + " ORDER BY recovered_at ASC, id ASC",
                RECOVERY_MAPPER, unitCode);
    }
}

